begin;
set local statement_timeout='15s';set local lock_timeout='2s';
do $$ declare p uuid:=gen_random_uuid();actor uuid;r jsonb;claim jsonb;token uuid;checks jsonb;begin
 select m.user_id into actor from public.platform_business_members m join public.platform_businesses b on b.id=m.business_id where b.slug='r-painters-llc' and m.role='owner' limit 1;assert actor is not null;
 insert into public.opportunities(id,title,source_name,source_url) values(p,'BUZZIE ROLLBACK WORKFLOW TEST','Synthetic rollback','https://example.invalid/buzzie-rollback-'||p);
 execute 'set local role service_role';
 checks:=jsonb_build_object('original_checked',true,'use_allowed',true,'hiring_intent',true,'open_confirmed',true,'contact_allowed',false,'public_contact','','published_at',now(),'deadline',null,'relationship','direct','priority','high','reason','Synthetic test only, never a customer','city','Summerville','project_type','Interior painting','description','Synthetic transactional workflow fixture');
 r:=public.buzzie_review_opportunity(p,gen_random_uuid(),0,'approved',checks);assert r->>'error'='forbidden','foreign actor';
 r:=public.buzzie_review_opportunity(p,actor,0,'approved',checks||'{"original_checked":false}');assert r->>'error'='invalid','unchecked original';
 r:=public.buzzie_review_opportunity(p,actor,0,'review',checks);assert r->>'revision'='1','review saved';
 r:=public.buzzie_review_opportunity(p,actor,0,'approved',checks);assert r->>'error'='conflict','stale review';
 r:=public.buzzie_claim_crm(p,actor,1);assert r->>'error'='not_configured','disabled connection';
 update public.buzzie_crm_config set manual_enabled=true;
 r:=public.buzzie_claim_crm(p,actor,1);assert r->>'error'='not_approved','review not approved';
 r:=public.buzzie_review_opportunity(p,actor,1,'approved',checks);assert r->>'revision'='2','approved saved';
 claim:=public.buzzie_claim_crm(p,actor,2);assert claim->'payload'->>'reference'='buzzie:'||p::text and claim->>'attempt'='1','claim snapshot';token:=(claim->>'lease_token')::uuid;
 r:=public.buzzie_claim_crm(p,actor,2);assert r->>'error'='busy_or_retry_limit','double dispatch';
 r:=public.buzzie_review_opportunity(p,actor,2,'dismissed',checks);assert r->>'error'='frozen','inflight immutable';
 assert not public.buzzie_finish_crm(p,gen_random_uuid(),gen_random_uuid(),'confirmed'),'foreign lease';
 assert public.buzzie_finish_crm(p,token,null,'connection_failed'),'failure recorded';
 r:=public.buzzie_claim_crm(p,actor,2);assert r->>'error'='busy_or_retry_limit','backoff';
 update public.buzzie_crm_outbox set retry_after=now()-interval '1 minute' where opportunity_id=p;
 update public.opportunities set title='Changed after first authorization' where id=p;
 claim:=public.buzzie_claim_crm(p,actor,2);assert claim->>'attempt'='2' and claim->'payload'->>'title'='BUZZIE ROLLBACK WORKFLOW TEST','stable retry';
 assert public.buzzie_finish_crm(p,(claim->>'lease_token')::uuid,gen_random_uuid(),'confirmed'),'mocked receiver confirmation';
 r:=public.buzzie_claim_crm(p,actor,2);assert r->>'already_sent'='true','confirmed not resent';
 assert (select count(*)=2 from public.buzzie_crm_attempts where opportunity_id=p),'attempts preserved';
 assert (select count(*)=2 from public.buzzie_opportunity_history where opportunity_id=p),'review history';
 assert not has_function_privilege('authenticated','public.buzzie_claim_crm(uuid,uuid,integer)','execute'),'client claim';
 assert not has_function_privilege('anon','public.buzzie_crm_secret()','execute'),'client secret';
 assert not has_table_privilege('authenticated','public.buzzie_crm_outbox','select'),'client outbox';
 assert (select relrowsecurity from pg_class where oid='public.buzzie_crm_outbox'::regclass),'outbox RLS';
end $$;
rollback;
select 22 as assertions_passed,(select count(*) from public.opportunities where source_url like 'https://example.invalid/buzzie-rollback-%') as fixture_rows_remaining;
